    allocated_goods = set()  # To keep track of already allocated goods

    # Sort goods by highest value for each person
    value_sorted = sorted([(p, g, v) for p, gv in values.items() for g, v in gv.items()],
                          key=lambda x: -x[2])

    for person, good, value in value_sorted:
        if good not in allocated_goods and len(allocation[person]) == 0:
            allocation[person].append(good)
            allocated_goods.add(good)

    # Handle money allocation
