import itertools

# Define the value matrix
values = {
    1: {'A': 45, 'B': 30, 'C': 25},
    2: {'A': 35, 'B': 40, 'C': 25},
    3: {'A': 50, 'B': 5, 'C': 45}
}

goods = ['A', 'B', 'C']
people = [1, 2, 3]

# Initialize the best allocation as None
best_allocation = None
best_fairness = float('-inf')  # We want to maximize the fairness

# Inclusive range function
def inclusive_range(start, end):
    return range(start, end+1)

# Calculate fairness index for a given allocation and money assignment
def calculate_fairness(allocation, money_distribution):
    person_value = {person: 0 for person in people}
    for person in people:
        for good in goods:
            if allocation[good] == person:
                person_value[person] += values[person][good]

    for person in people:
        person_value[person] += money_distribution[person]

    min_value = min(person_value.values())
    max_value = max(person_value.values())

    fairness_index = min_value / max_value if max_value > 0 else 0
    return fairness_index, person_value 

# Brute-force search over all possible allocations
for allocation in itertools.product(people + [None], repeat=len(goods)):  
    allocation_map = dict(zip(goods, allocation))

    # Brute-force search over possible monetary distributions
    for m1 in inclusive_range(0, 5):
        for m2 in inclusive_range(0, 5 - m1):
            for m3 in inclusive_range(0, 5 - m1 - m2):
                money_distribution = {1: m1, 2: m2, 3: m3}

                # Calculate fairness and compare it with the previous best
                fairness_index, person_value = calculate_fairness(allocation_map, money_distribution)
                if fairness_index > best_fairness:
                    best_fairness = fairness_index
                    best_allocation = (allocation_map, money_distribution, person_value)

# Print the best allocation and money assignment
best_goods_allocation, best_money_distribution, best_person_values = best_allocation
print("Best Goods Allocation:", best_goods_allocation)
print("Best Money Distribution:", best_money_distribution)
print("Best Person Values:", best_person_values)
