def find_fair_allocation(values, goods, total_money):
    from itertools import permutations, product
    import numpy as np

    n = len(values)
    people = list(values.keys())
    all_permutations = list(product(permutations(people), repeat=len(goods)))
    best_allocation = None
    best_fairness = float('inf')

    for perm in all_permutations:
        current_allocation = {person: {"Value": 0, "Goods": [], "Money": 0} for person in people}
        for i, good in enumerate(goods):
            current_allocation[perm[i][i]]["Value"] += values[perm[i][i]][good]
            current_allocation[perm[i][i]]["Goods"].append(good)

        values_list = [current_allocation[person]["Value"] for person in people]
        money_distribution = np.linspace(0, total_money, num=total_money * len(people))
        for money_combination in product(money_distribution, repeat=n):
            if sum(money_combination) <= total_money:
                new_values_list = [values_list[i] + money_combination[i] for i in range(n)]
                current_fairness = max(new_values_list) - min(new_values_list)

                if current_fairness < best_fairness:
                    best_fairness = current_fairness
                    final_allocation = {
                        person: {
                            "Goods": current_allocation[person]["Goods"],
                            "Money": money_combination[idx]
                        }
                        for idx, person in enumerate(people)
                    }

    return final_allocation

allocation = find_fair_allocation(values, goods, total_money)

# Allocate the goods and money based on the best allocation found
for person in allocation:
    for good in allocation[person]["Goods"]:
        allocation[person][good] = 1
    allocation[person]["Money"] = allocation[person]["Money"]

# Print the final allocation
for person in allocation:
    print(f"Person {person} receives: Goods: {allocation[person]['Goods']} Money: {allocation[person]['Money']} units")

