```python
# Values of goods for each person
values = {
    'Person 1': {'A': 45, 'B': 30, 'C': 25},
    'Person 2': {'A': 35, 'B': 40, 'C': 25},
    'Person 3': {'A': 50, 'B': 5, 'C': 45}
}

# function to allocate the goods and money
def fair_allocation(values, total_money):
    allocation = {'Person 1': {'goods': [], 'money': 0},
                  'Person 2': {'goods': [], 'money': 0},
                  'Person 3': {'goods': [], 'money': 0}}

    goods = ['A', 'B', 'C']
    taken_goods = {goods: False for goods in goods}

    # Sort persons by their highest single good value
    sorted_persons_by_value = sorted(values.keys(), key=lambda p: -max(values[p].values()))

    for person in sorted_persons_by_value:
        person_alloc = allocation[person]
        # Assign that person their highest valued good if it is not taken already
        highest_valued_good = max(values[person], key=values[person].get)
        if not taken_goods[highest_valued_good]:
            person_alloc['goods'].append(highest_valued_good)
            taken_goods[highest_valued_good] = True

    # Check remaining goods and assign them to the person who values them most and hasn't got any good yet
    for good in taken_goods:
        if not taken_goods[good]:
            best_person = max(values, key=lambda p: values[p][good] if len(allocation[p]['goods']) == 0 else -1)
            allocation[best_person]['goods'].append(good)
            taken_goods[good] = True

    # Distribute money
    remaining_money = total_money
    for person in sorted_persons_by_value:
        if len(allocation[person]['goods']) == 0:
            person_value_sum = sum(values[person][good] for good in values[person])
            person_money = min(remaining_money, person_value_sum / total_money)
            allocation[person]['money'] += person_money
            remaining_money -= person_money

    # Allocate remaining money proportionally if any person got money but not goods
    if remaining_money > 0:
        sum_value_no_good = sum(values[person][good] for person in allocation for good in allocation[person]['goods'])
        for person in allocation:
            if len(allocation[person]['goods']) == 0 and sum_value_no_good > 0:
                share_money = remaining_money * sum(values[person].values()) / sum_value_no_good
                allocation[person]['money'] += share_money

    return allocation

# Allocate the goods and money
total_money = 5
allocation_result = fair_allocation(values, total_money)

# Print the allocation result
for person, alloc in allocation_result.items():
    print(f"{person}: Goods: {alloc['goods']}, Money: {alloc['money']} units")
```

