def allocate_goods_and_money():
    global total_money, goods_available

    # Sort persons by the highest value they place on any single good
    persons_sorted = sorted(values.keys(), key=lambda x: max(values[x].values()), reverse=True)

    # Allocate the goods
    for person in persons_sorted:
        for good in goods_available:
            if good in values[person] and values[person][good] == max(values[person].values()):
                allocations[person]['goods'].append(good)
                goods_available.remove(good)
                break

    # Distribute the remaining money
    persons_values = {p: sum([values[p][g] for g in allocations[p]['goods']]) for p in allocations.keys()}
    total_value = sum(persons_values.values())
    for person in allocations:
        if total_value > 0:
            share = (persons_values[person] / total_value) * total_money
        else:
            share = total_money / len(allocations)
        allocations[person]['money'] = share
        total_money -= share

# Run the allocation procedure
allocate_goods_and_money()

# Print the final allocations
for person in allocations:
    print(f"{person}: Goods = {allocations[person]['goods']}, Money = {allocations[person]['money']:.2f}")
