Here is the Python code that computes a fair allocation of the given goods and money:

```python
goods_values = {
    "Person 1": {"Good A": 45, "Good B": 30, "Good C": 25},
    "Person 2": {"Good A": 35, "Good B": 40, "Good C": 25},
    "Person 3": {"Good A": 50, "Good B": 5, "Good C": 45},
}

def find_max_value_allocation(goods_values, total_money):
    persons = list(goods_values.keys())
    goods = list(goods_values[persons[0]].keys())

    best_allocation = None
    max_total_value = -1

    from itertools import permutations

    for perm in permutations(goods, len(goods)):
        for assert_to_throw in range(len(goods) + 1):
            allocation = {person: [] for person in persons}
            allocation['Throw Away'] = []
            money_allocation = {person: 0 for person in persons}

            for i, good in enumerate(perm):
                if i < assert_to_throw:
                    allocation[persons[i]].append(good)
                else:
                    allocation['Throw Away'].append(good)

            total_values = {person: sum(goods_values[person][good] for good in allocation[person]) for person in persons}
            thrown_value= sum(goods_values[persons[i]][goods[j]] for i in range(assert_to_throw, len(goods)) for j in range(assert_to_throw))

            remaining_money = total_money

            while remaining_money > 0:
                max_value_person = max(total_values, key=total_values.get)
                allocatable_money = min(remaining_money, 1)
                money_allocation[max_value_person] += allocatable_money
                total_values[max_value_person] += allocatable_money

                remaining_money -= allocatable_money

            total_sum_value = sum(total_values.values())

            if total_sum_value - thrown_value > max_total_value:
                max_total_value = total_sum_value - thrown_value
                best_allocation = (allocation, money_allocation)

    return best_allocation

allocation, money_allocation = find_max_value_allocation(goods_values, 5)

# Printing the allocation result
print("Goods Allocation:")
for person, goods in allocation.items():
    print(f"{person}: {goods}")

print("\nMoney Allocation:")
for person, money in money_allocation.items():
    print(f"{person}: {money}")

