from itertools import permutations

# Define the values for each person
values = {
    1: {'A': 45, 'B': 30, 'C': 25},
    2: {'A': 35, 'B': 40, 'C': 25},
    3: {'A': 50, 'B': 5, 'C': 45}
}

# List of goods and people
