people = [1, 2, 3]

# Initialize best allocation and best fair value
best_allocation = None
best_fair_value = float('-inf')

# Helper function to calculate the fair value of an allocation.
def calculate_fair_value(allocation, values):
    fair_values = [0, 0, 0]
    for person_id, allocated_goods in allocation.items():
        for good in allocated_goods:
            fair_values[person_id - 1] += values[person_id][good]
        if allocation["money"][person_id - 1] > 0:
            fair_values[person_id - 1] += allocation["money"][person_id - 1]
    return min(fair_values)

# Iterate through all permutations of assigning goods to people
for perm in permutations(goods):
    all_money_allocations = [
        (m1, m2, 5 - m1 - m2) 
        for m1 in range(6) 
        for m2 in range(6 - m1)
    ]
    for money_allocation in all_money_allocations:
        allocation = {
            1: [perm[0]], 
            2: [perm[1]], 
            3: [perm[2]],
            'money': money_allocation
        }
        fair_value = calculate_fair_value(allocation, values)
        if fair_value > best_fair_value:
            best_fair_value = fair_value
            best_allocation = allocation

# Output the best allocation
print(f"Best Allocation: {best_allocation}")
print(f"Best Fair Value: {best_fair_value}")
