# This function helps to find the best way to allocate one good optimally
def find_best_allocation(values, good):
    best_person = None
    best_value = 0
    for person in values:
        if values[person][good] > best_value:
            best_value = values[person][good]
            best_person = person
    return best_person

# Allocate each good optimally
